'use strict';
// Turns a scenario (static JSON or generated by a family) + the defaults into the effective settings for one platform.
var datasets = require('./datasets');

function merge(a, b) { var o = {}, k; for (k in a) o[k] = a[k]; for (k in (b || {})) o[k] = b[k]; return o; }

// clockTimezone: "host" (the emulator shows the host's local time - default) or "utc" (the emulator shows UTC).
function clockInstant(clock, tzMode) {
  var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(clock.date), t = /^(\d{1,2}):(\d{2}):(\d{2})$/.exec(clock.time);
  if (!m) throw new Error('clock.date must be YYYY-MM-DD, got "' + clock.date + '"');
  if (!t) throw new Error('clock.time must be HH:MM:SS, got "' + clock.time + '"');
  var pad = function (n) { return ('0' + n).slice(-2); };
  var iso = clock.date + 'T' + pad(+t[1]) + ':' + t[2] + ':' + t[3];
  var ms = tzMode === 'utc' ? Date.UTC(+m[1], +m[2] - 1, +m[3], +t[1], +t[2], +t[3]) : new Date(iso).getTime();
  return { nowIso: iso, unix: Math.floor(ms / 1000) };
}

function resolve(sc, defaults, platform, cli) {
  var ov = (sc.platformOverrides || {})[platform] || {};
  var pd = (defaults.platformDefaults || {})[platform] || {};
  var s = merge(sc, ov);
  var clock = merge(merge(defaults.clock, sc.clock), ov.clock);
  var inst = clockInstant(clock, cli.clockTimezone || 'host');
  var data = null;
  if (!s.noData) data = datasets.deepMerge(datasets.deepMerge(defaults.data || {}, sc.data), ov.data);
  var eff = {
    name: sc.name, platform: platform, exampleStyle: s.exampleStyle || 0,
    preset: merge(merge(pd.preset, sc.preset), ov.preset),
    settingsBase: merge(defaults.settings, pd.settings),
    settingsAfter: merge(merge(merge(defaults.settingsAfter, pd.settingsAfter), sc.settings), ov.settings),
    dataset: s.dataset || defaults.dataset, data: data, location: merge(defaults.location, s.location),
    nowIso: inst.nowIso
  };
  if (s.noData) eff.data = null;
  return {
    eff: eff,
    clock: { format: clock.format, unix: inst.unix, time: clock.time, date: clock.date },
    battery: merge(merge(defaults.battery, sc.battery), ov.battery),
    bluetooth: s.bluetooth !== undefined ? s.bluetooth : defaults.bluetooth,
    settleMs: s.settleMs || defaults.settleMs,
    doubleSetTime: s.doubleSetTime !== undefined ? s.doubleSetTime : !!defaults.doubleSetTime,
    retries: s.retries !== undefined ? s.retries : (defaults.retries || 0),
    tolerance: merge(merge(merge({ channelTolerance: 0, maxDiffPixels: 0 }, defaults.tolerance), s.tolerance), (sc.toleranceByPlatform || {})[platform])
  };
}

module.exports = { resolve: resolve, clockInstant: clockInstant, merge: merge };
